window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5398aad1d66b4955"]={"versions": [{"id": "FIG-5398aad1d66b4955", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit bedingtem Fragment <code>opt</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code> (Kapitel 11.5 <em>Platform Health Management</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Standard-Fehlerbehandlungspfad (<em>Default Scenario</em>) bei Verletzung einer Überwachungsbedingung (Supervision Failure). Es beschreibt die Interaktion zwischen überwachter Applikation, Überwachungsinstanz (<strong>PHM</strong>), zentraler Zustands- und Recovery-Steuerung (<strong>SM</strong>) sowie dem Hardware-/System-<strong>Watchdog</strong> zur Absicherung funktionaler Sicherheit (ISO 26262).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten (Lifelines):</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code>: Standard-Benutzerprozess im User Space, der Checkpoints an das Health Management meldet.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code>: Adaptiver Funktionscluster (PHM) zur Auswertung von Alive-, Deadline- und Logical-Supervisions.\n</li><li><code>«aapFunctionalCluster» :State Management</code>: Adaptiver Funktionscluster (SM) zur systemweiten Koordination von Function Groups, Machine States und Recovery Actions.\n</li><li><code>:Watchdog</code>: Abstrahierte Plattform-/Hardware-Watchdog-Entität (Watchdog Driver / Daemon) zur Ausführung harter Systemreaktionen (Machine Reset).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Methodenaufrufe:</strong>\n<ul class=\"fig-list\"><li><code>Offer()</code>: Registrierungsmethode von SM bei PHM zur Bereitstellung des Recovery-Dienstes.\n</li><li><code>ReportCheckpoint(wrongCheckpointId)</code>: API-Aufruf von Applikationsseite an PHM (z. B. via <code>ara::phm</code>).\n</li><li><code>handleSupervisionFailure()</code>: PHM-interne Zustandsauswertung und Fehlerverarbeitung.\n</li><li><code>RecoveryHandler()</code>: Callback-/Notification-Interface von PHM an SM zur Einleitung softwarebasierter Wiederherstellungsmaßnahmen.\n</li><li><code>FireWatchdogReaction()</code>: Eskalationsaufruf von PHM an den Watchdog bei Ausbleiben der Reaktion durch SM.\n</li><li><code>StopOffer()</code>: Deregistrierungsmethode von SM bei Einleitung des Shutdowns.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Präbedingung (Initialisierung):</strong>\n<ul class=\"fig-list\"><li><code>:State Management</code> ruft intern/lokal <code>Offer()</code> auf, um sich beim PHM als aktiver Empfänger für Überwachungsfehler zu registrieren.\n</li></ul>\n</li><li><strong>Fehler-Trigger:</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code> sendet <code>ReportCheckpoint(wrongCheckpointId)</code>. Dies repräsentiert beispielhaft eine Transition-Verletzung innerhalb einer <em>Logical Supervision</em> (Graph-Inkonsistenz).\n</li></ul>\n</li><li><strong>Fehleranalyse &amp; Signalisierung:</strong>\n<ul class=\"fig-list\"><li>PHM erkennt den Überwachungsfehler und führt synchron <code>handleSupervisionFailure()</code> aus.\n</li><li>PHM delegiert die Fehlerbehebung über den Callback <code>RecoveryHandler()</code> asynchron/synchron an <code>:State Management</code>.\n</li></ul>\n</li><li><strong>Eskalationspfad (<code>opt [timeout]</code>):</strong>\n<ul class=\"fig-list\"><li>Läuft der im Manifest konfigurierte Timeout ab, bevor <code>:State Management</code> die Bearbeitung von <code>RecoveryHandler()</code> abschließt bzw. quittiert, greift der <code>opt</code>-Zweig:\n</li><li>PHM triggert direkt <code>FireWatchdogReaction()</code> am <code>:Watchdog</code>, um einen deterministischen Maschinen-Neustart (<em>Machine Reset / Fail-Safe Transition</em>) zu erzwingen.\n</li></ul>\n</li><li><strong>Postcondition / Shutdown:</strong>\n<ul class=\"fig-list\"><li>Beim regulären oder fehlerbedingten Herunterfahren ruft <code>:State Management</code> <code>StopOffer()</code> auf, um weitere Aufrufe von <code>RecoveryHandler()</code> durch PHM zu unterbinden.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PHM-Manifest-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Für jede definierte Supervision (Alive, Deadline, Logical) muss im Execution-/Health-Manifest zwingend ein definierter Timeout für die Rückmeldung des SM-Recovery-Handlers hinterlegt werden.\n</li><li>Der Watchdog-Reaktionspfad (<code>FireWatchdogReaction</code>) dient als harte Sicherheitsbarriere gegen blockierende oder abgestürzte State-Management-Instanzen.\n</li></ul>\n</li><li><strong>State Management Implementierung:</strong>\n<ul class=\"fig-list\"><li>Der <code>RecoveryHandler()</code> muss strikt nicht-blockierend ausgelegt sein. Länger dauernde Recovery-Aktionen (z. B. Neustart einer Prozessgruppe via Execution Management) müssen asynchron angestoßen werden, um den harten Watchdog-Timeout nicht zu verletzen.\n</li><li>Vor dem Eintritt in den Shutdown-State muss SM deterministisch <code>StopOffer()</code> aufrufen, um Race Conditions mit spät eintreffenden PHM-Meldungen zu verhindern.\n</li></ul>\n</li><li><strong>Applikations-Entwicklung (<code>ara::phm</code>):</strong>\n<ul class=\"fig-list\"><li>Checkpoint-IDs müssen exakt den im Modell definierten Transitionsgraphen entsprechen. Ungültige Checkpoint-Sequenzen werden deterministisch als <em>Supervision Failure</em> gewertet und eskalieren platformweit.\n</li></ul>\n</li></ul>"}, {"id": "FIG-00f03948ae751d9a", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm mit kombiniertem Fragment <code>alt</code> mit drei Alternativpfaden).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Releases R24-11 und R25-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code> (Kapitel 11.5 <em>Platform Health Management</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Standard-Fehlerbehandlungspfad (<em>Default Scenario</em>) bei Verletzung einer Überwachungsbedingung (Supervision Failure). Es beschreibt die Interaktion zwischen überwachter Applikation, Überwachungsinstanz (<strong>PHM</strong>), zentraler Zustands- und Recovery-Steuerung (<strong>SM</strong>) sowie dem Hardware-/System-<strong>Watchdog</strong> zur Absicherung funktionaler Sicherheit (ISO 26262).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten (Lifelines):</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code>: Standard-Benutzerprozess im User Space, der Checkpoints an das Health Management meldet.\n</li><li><code>«aapFunctionalCluster» :Platform Health Management</code>: Adaptiver Funktionscluster (PHM) zur Auswertung von Alive-, Deadline- und Logical-Supervisions.\n</li><li><code>«aapFunctionalCluster» :State Management</code>: Adaptiver Funktionscluster (SM) zur systemweiten Koordination von Function Groups, Machine States und Recovery Actions.\n</li><li><code>:Watchdog</code>: Abstrahierte Plattform-/Hardware-Watchdog-Entität (Watchdog Driver / Daemon) zur Ausführung harter Systemreaktionen (Machine Reset).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Methodenaufrufe:</strong>\n<ul class=\"fig-list\"><li><code>Offer()</code>: Registrierungsmethode von SM bei PHM zur Bereitstellung des Recovery-Dienstes.\n</li><li><code>ReportCheckpoint(wrongCheckpointId)</code>: API-Aufruf von Applikationsseite an PHM (z. B. via <code>ara::phm</code>).\n</li><li><code>«aapInformative» handleSupervisionFailure()</code>: PHM-interne, rein informative Fehleranalyse und Zustandsauswertung.\n</li><li><code>RecoveryHandler()</code>: Callback-/Notification-Interface von PHM an SM zur Einleitung von Recovery-Maßnahmen, mit synchroner Rückmeldung (<code>:kActionHandled</code> oder <code>:kFireWatchdogReaction</code>).\n</li><li><code>:kActionHandled</code>: Rückgabewert/Antwortnachricht von SM an PHM bei erfolgreicher lokaler Fehlerbehandlung.\n</li><li><code>:kFireWatchdogReaction</code>: Rückgabewert/Antwortnachricht von SM an PHM zur expliziten Beauftragung einer Watchdog-Eskalation.\n</li><li><code>FireWatchdogReaction()</code>: Aufruf von PHM an den Watchdog zur Auslösung eines Maschinen-Resets (angefordert durch SM oder durch Timeout).\n</li><li><code>StopOffer()</code>: Deregistrierungsmethode von SM bei Einleitung des Shutdowns.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Präbedingung (Initialisierung):</strong>\n<ul class=\"fig-list\"><li><code>:State Management</code> ruft lokal <code>Offer()</code> auf, um sich beim PHM als aktiver Empfänger für Überwachungsfehler zu registrieren.\n</li></ul>\n</li><li><strong>Fehler-Trigger:</strong>\n<ul class=\"fig-list\"><li><code>:Adaptive Application</code> sendet <code>ReportCheckpoint(wrongCheckpointId)</code>. Dies repräsentiert beispielhaft eine Transition-Verletzung innerhalb einer <em>Logical Supervision</em> (Graph-Inkonsistenz).\n</li></ul>\n</li><li><strong>Fehleranalyse &amp; Signalisierung:</strong>\n<ul class=\"fig-list\"><li>PHM erkennt den Überwachungsfehler und führt intern <code>«aapInformative» handleSupervisionFailure()</code> aus.\n</li><li>PHM delegiert die Fehlerbehebung über den Aufruf <code>RecoveryHandler()</code> an <code>:State Management</code>.\n</li></ul>\n</li><li><strong>Verzweigung im Fehlerbehandlungspfad (<code>alt</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad 1 (<code>[action handled]</code>):</strong> <code>:State Management</code> behandelt den Fehler erfolgreich (z. B. Prozess-Neustart) und antwortet mit <code>:kActionHandled</code>. PHM unternimmt keine weiteren Schritte.\n</li><li><strong>Pfad 2 (<code>[watchdog reaction requested]</code>):</strong> <code>:State Management</code> entscheidet auf Systemebene, dass eine Watchdog-Aktion erforderlich ist, und antwortet mit <code>:kFireWatchdogReaction</code>. PHM ruft daraufhin <code>FireWatchdogReaction()</code> am <code>:Watchdog</code> auf.\n</li><li><strong>Pfad 3 (<code>[timeout]</code>):</strong> Antwortet <code>:State Management</code> nicht innerhalb des im Manifest konfigurierten Timeouts, greift der Timeout-Pfad und PHM ruft autonom <code>FireWatchdogReaction()</code> am <code>:Watchdog</code> auf.\n</li></ul>\n</li><li><strong>Postcondition / Shutdown:</strong>\n<ul class=\"fig-list\"><li>Beim regulären oder fehlerbedingten Herunterfahren ruft <code>:State Management</code> <code>StopOffer()</code> auf, um weitere Aufrufe von <code>RecoveryHandler()</code> durch PHM zu unterbinden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Schnittstellen &amp; Statuscodes:</strong>\n<ul class=\"fig-list\"><li>Der Methodenaufruf <code>RecoveryHandler()</code> fordert eine explizite Rückmeldung von <code>:State Management</code> mit den definierten Rückgabewerten <code>:kActionHandled</code> (Erfolg der lokalen Wiederherstellung) oder <code>:kFireWatchdogReaction</code> (Eskalationsanforderung an PHM).\n</li><li>Nur bei Ausbleiben dieser Rückmeldung innerhalb des im Manifest definierten Timeouts ist PHM autorisiert, eigenständig <code>FireWatchdogReaction()</code> auszulösen.\n</li></ul>\n</li><li><strong>Informative Bestandteile:</strong>\n<ul class=\"fig-list\"><li>Die Methode <code>handleSupervisionFailure()</code> ist mit dem Stereotyp <code>«aapInformative»</code> gekennzeichnet; ihre konkrete Realisierung innerhalb des PHM ist nicht normativ vorgeschrieben, sondern dient als Implementierungsleitfaden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-5398aad1d66b4955", "to": "FIG-00f03948ae751d9a", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Kombiniertes Fragment:</strong> Ersetzung des bedingten Fragments <code>opt [timeout]</code> durch ein Alternativ-Fragment <code>alt</code> mit drei Zweigen (<code>[action handled]</code>, <code>[watchdog reaction requested]</code>, <code>[timeout]</code>).\n</li><li><strong>Schnittstelle / Antwortnachrichten <code>RecoveryHandler()</code>:</strong> Ergänzung der Rückgabewerte <code>:kActionHandled</code> (im Zweig <code>[action handled]</code>) und <code>:kFireWatchdogReaction</code> (im Zweig <code>[watchdog reaction requested]</code>) von <code>:State Management</code> an <code>:Platform Health Management</code>.\n</li><li><strong>Ablauf <code>FireWatchdogReaction()</code>:</strong> Auslösung am <code>:Watchdog</code> erfolgt nun zusätzlich explizit nach Erhalt von <code>:kFireWatchdogReaction</code> im Zweig <code>[watchdog reaction requested]</code>.\n</li><li><strong>Methode <code>handleSupervisionFailure()</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code>.\n</li><li><strong>Aktivierungsbalken (<code>:State Management</code>):</strong> Verlängerung des Aktivierungsbalkens auf der Lebenslinie von <code>:State Management</code> bis zum Senden der jeweiligen Antwortnachricht.\n</li></ul>"}]};
